This Terraform configuration creates an AWS RDS MySQL 5.7 database instance with:

- 200 GB allocated storage
- `db.t3.micro` instance class
- Randomly generated admin password
- Public accessibility enabled
- Security group allowing inbound MySQL access on port `3306` from the internet
- Deployment into the default VPC and its default subnets

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the RDS instance will be created."
  type        = string
  default     = "us-east-1"
}

variable "db_username" {
  description = "Master username for the MySQL database."
  type        = string
  default     = "admin"
}

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
